-- Account identity proof with synthetic people and teams; all rows roll back.
begin;
create temporary table card_checks(label text primary key,ok boolean not null);
create function pg_temp.card_ok(label text,value boolean) returns void language plpgsql security definer as $$begin
 if value is distinct from true then raise exception 'CARD FAIL: %',label;end if;
 insert into pg_temp.card_checks values(label,true);end $$;
create function pg_temp.card_denied(label text,statement text,message text)returns void language plpgsql as $$declare e text;begin
 begin execute statement;exception when others then e:=sqlerrm;end;
 if e is null or position(message in e)=0 then raise exception 'CARD FAIL: % wrong denial: %',label,coalesce(e,'accepted');end if;
 perform pg_temp.card_ok(label,true);end $$;
insert into auth.users(id,email,is_anonymous) values
 ('ca100501-0000-4000-8000-000000000001','private-owner@fixture.invalid',false),
 ('ca100501-0000-4000-8000-000000000002','private-member@fixture.invalid',false),
 ('ca100501-0000-4000-8000-000000000003','private-other@fixture.invalid',false);
create temporary table card_fixture as select user_id actor,org_id org from memberships where user_id::text like 'ca100501-%';
grant select on card_fixture to service_role,authenticated;
update profiles set name=case id when 'ca100501-0000-4000-8000-000000000001' then 'Owner Person' when 'ca100501-0000-4000-8000-000000000002' then 'Member Person' else 'Other Person'end where id::text like 'ca100501-%';
update orgs set brand_kit='{"name":"Inviter Agency","email":"inviter-public@fixture.invalid","phone":"5551110001","brokerage":"Office Brand","accent":"#123456"}' where id in(select org from card_fixture);
insert into listings(id,org_id,agent_id,address)select 'ca100502-0000-4000-8000-000000000001',org,actor,'Synthetic listing'from card_fixture where actor='ca100501-0000-4000-8000-000000000001';
select pg_temp.card_ok('personal card column cannot be directly updated',not has_column_privilege('authenticated','profiles','public_card','UPDATE') and not has_column_privilege('anon','profiles','public_card','UPDATE'));
select pg_temp.card_ok('personal card helpers are service only',not has_function_privilege('authenticated','read_personal_public_card(uuid)','EXECUTE') and not has_function_privilege('anon','merge_personal_public_card(uuid,jsonb,jsonb)','EXECUTE') and not has_function_privilege('authenticated','public_listing_agent_identity(uuid)','EXECUTE'));
set local role service_role;
select pg_temp.card_ok('new account has no public card or login email',(read_personal_public_card('ca100501-0000-4000-8000-000000000002')->'public_card')='null'::jsonb and position('private-member'in read_personal_public_card('ca100501-0000-4000-8000-000000000002')::text)=0);
select pg_temp.card_ok('legacy sole-owner published contact is preserved',(public_listing_agent_identity('ca100502-0000-4000-8000-000000000001')->>'legacy_owned_single_member')='true' and public_listing_agent_identity('ca100502-0000-4000-8000-000000000001')->'legacy_brand'->>'email'='inviter-public@fixture.invalid');
reset role;
insert into memberships(org_id,user_id,role)select org,'ca100501-0000-4000-8000-000000000002','agent'from card_fixture where actor='ca100501-0000-4000-8000-000000000001';
update listings set agent_id='ca100501-0000-4000-8000-000000000002'where id='ca100502-0000-4000-8000-000000000001';
set local role service_role;
select pg_temp.card_ok('team join never copies inviter contact',(public_listing_agent_identity('ca100502-0000-4000-8000-000000000001')->>'profile_name')='Member Person' and (public_listing_agent_identity('ca100502-0000-4000-8000-000000000001')->>'legacy_owned_single_member')='false' and public_listing_agent_identity('ca100502-0000-4000-8000-000000000001')->'legacy_brand'='{}');
select merge_personal_public_card('ca100501-0000-4000-8000-000000000002','{"space_type":"real_estate","name":"Member Public","email":"reviewed@fixture.invalid","phone":"5552220002"}','{"space_type":{"present":false},"name":{"present":false},"email":{"present":false},"phone":{"present":false}}');
select pg_temp.card_ok('agent saves own card without workspace admin',(read_personal_public_card('ca100501-0000-4000-8000-000000000002')->'public_card'->>'name')='Member Public');
select pg_temp.card_ok('card save never changes private login or org brand',(select email='private-member@fixture.invalid' and name='Member Person'from profiles where id='ca100501-0000-4000-8000-000000000002') and (select brand_kit->>'name'='Inviter Agency'from orgs where id=(select org from card_fixture where actor='ca100501-0000-4000-8000-000000000001')));
select pg_temp.card_ok('public listing uses exact assigned person',(public_listing_agent_identity('ca100502-0000-4000-8000-000000000001')->'personal_card'->>'email')='reviewed@fixture.invalid' and (public_listing_agent_identity('ca100502-0000-4000-8000-000000000001')->'org_business'->>'brokerage')='Office Brand');
select pg_temp.card_ok('other account still has no card',(read_personal_public_card('ca100501-0000-4000-8000-000000000003')->'public_card')='null');
select merge_personal_public_card('ca100501-0000-4000-8000-000000000002','{"website":"https://member.fixture.invalid"}','{"website":{"present":false}}');
select merge_personal_public_card('ca100501-0000-4000-8000-000000000002','{"phone":"5552229999"}','{"phone":{"present":true,"value":"5552220002"}}');
select pg_temp.card_ok('unrelated field merge preserves existing contact',(read_personal_public_card('ca100501-0000-4000-8000-000000000002')->'public_card'->>'website')='https://member.fixture.invalid');
select pg_temp.card_denied('stale same-field save conflicts','select merge_personal_public_card(''ca100501-0000-4000-8000-000000000002'',''{"phone":"wrong"}'',''{"phone":{"present":true,"value":"5552220002"}}'')','RP409');
select merge_personal_public_card('ca100501-0000-4000-8000-000000000002','{"phone":"5552229999"}','{"phone":{"present":true,"value":"5552220002"}}');
select pg_temp.card_ok('lost matching receipt replay preserves later unrelated fields',(read_personal_public_card('ca100501-0000-4000-8000-000000000002')->'public_card'->>'website')='https://member.fixture.invalid');
select merge_personal_public_card('ca100501-0000-4000-8000-000000000002','{"email":null}','{"email":{"present":true,"value":"reviewed@fixture.invalid"}}');
select pg_temp.card_ok('explicit contact clearing does not use login email',not(read_personal_public_card('ca100501-0000-4000-8000-000000000002')->'public_card'?'email'));
select pg_temp.card_denied('system and org fields refused','select merge_personal_public_card(''ca100501-0000-4000-8000-000000000002'',''{"business_logo_url":"https://evil.fixture.invalid/logo.png"}'',''{"business_logo_url":{"present":false}}'')','RP400');
select pg_temp.card_denied('javascript URL injection refused','select merge_personal_public_card(''ca100501-0000-4000-8000-000000000002'',''{"website":"javascript:alert(1)"}'',''{"website":{"present":false}}'')','RP400');
select pg_temp.card_denied('URL credential injection refused','select merge_personal_public_card(''ca100501-0000-4000-8000-000000000002'',''{"website":"https://user@evil.fixture.invalid"}'',''{"website":{"present":false}}'')','RP400');
select pg_temp.card_denied('unknown industry refused','select merge_personal_public_card(''ca100501-0000-4000-8000-000000000002'',''{"space_type":"foreign"}'',''{"space_type":{"present":false}}'')','RP400');
select pg_temp.card_denied('missing presence marker refused','select merge_personal_public_card(''ca100501-0000-4000-8000-000000000002'',''{"name":"Wrong"}'',''{"name":{}}'')','RP400');
select pg_temp.card_denied('presence true without value refused','select merge_personal_public_card(''ca100501-0000-4000-8000-000000000002'',''{"name":"Wrong"}'',''{"name":{"present":true}}'')','RP400');
select pg_temp.card_denied('oversized personal field refused','select merge_personal_public_card(''ca100501-0000-4000-8000-000000000002'',jsonb_build_object(''name'',repeat(''x'',121)),''{"name":{"present":false}}'')','RP400');
reset role;
delete from memberships where user_id='ca100501-0000-4000-8000-000000000002'and org_id=(select org from card_fixture where actor='ca100501-0000-4000-8000-000000000001');
set local role service_role;
select pg_temp.card_ok('removed team member has no public listing identity',(public_listing_agent_identity('ca100502-0000-4000-8000-000000000001')->'personal_card')='null' and (public_listing_agent_identity('ca100502-0000-4000-8000-000000000001')->'profile_name')='null');
select pg_temp.card_ok('removing membership does not erase own account card',(read_personal_public_card('ca100501-0000-4000-8000-000000000002')->'public_card'->>'name')='Member Public');
reset role;
insert into memberships(org_id,user_id,role)select org,'ca100501-0000-4000-8000-000000000002','agent'from card_fixture where actor='ca100501-0000-4000-8000-000000000001';
set local role service_role;
select prepare_account_deletion('ca100501-0000-4000-8000-000000000002','fixture-uploads','fixture-renders');
select pg_temp.card_denied('pending deletion refuses account card write','select merge_personal_public_card(''ca100501-0000-4000-8000-000000000002'',''{"name":"Wrong"}'',''{"name":{"present":false}}'')','RP403');
select pg_temp.card_denied('pending deletion refuses account card read','select read_personal_public_card(''ca100501-0000-4000-8000-000000000002'')','RP403');
select pg_temp.card_ok('pending deletion hides public personal contact',(public_listing_agent_identity('ca100502-0000-4000-8000-000000000001')->'personal_card')='null');
reset role;
select set_config('request.jwt.claim.sub','ca100501-0000-4000-8000-000000000003',true);
set local role authenticated;
select pg_temp.card_denied('authenticated cannot bypass explicit own-card CAS','update profiles set public_card=''{}'' where id=''ca100501-0000-4000-8000-000000000003''','permission denied');
select pg_temp.card_denied('authenticated cannot invoke service helper','select read_personal_public_card(''ca100501-0000-4000-8000-000000000001'')','permission denied');
reset role;
update listings set deleted_at=now()where id='ca100502-0000-4000-8000-000000000001';
set local role service_role;
select pg_temp.card_denied('deleted listing cannot resolve identity','select public_listing_agent_identity(''ca100502-0000-4000-8000-000000000001'')','RP404');
select merge_personal_public_card('ca100501-0000-4000-8000-000000000003','{"name":null}','{"name":{"present":false}}');
select pg_temp.card_ok('explicit empty card differs from never-saved null',read_personal_public_card('ca100501-0000-4000-8000-000000000003')->'public_card'='{}'::jsonb);
reset role;
insert into listings(id,org_id,agent_id,address)select 'ca100502-0000-4000-8000-000000000003',org,actor,'Synthetic solo listing'from card_fixture where actor='ca100501-0000-4000-8000-000000000003';
insert into capture_assets(id,listing_id,kind,bucket,storage_key,uploaded)select 'ca100503-0000-4000-8000-000000000003','ca100502-0000-4000-8000-000000000003','photo','renders','renders/'||org||'/ca100502-0000-4000-8000-000000000003/owned-portrait.jpg',true from card_fixture where actor='ca100501-0000-4000-8000-000000000003';
update orgs set brand_kit=brand_kit||jsonb_build_object('headshot_url','https://cdn.fixture.invalid/renders/'||id||'/ca100502-0000-4000-8000-000000000003/owned-portrait.jpg')where id=(select org from card_fixture where actor='ca100501-0000-4000-8000-000000000003');
set local role service_role;
select pg_temp.card_ok('explicit own card preserves proven legacy owned portrait',(public_listing_agent_identity('ca100502-0000-4000-8000-000000000003')->'legacy_portrait'->>'asset_id')='ca100503-0000-4000-8000-000000000003');
reset role;
insert into capture_assets(id,listing_id,kind,bucket,storage_key,uploaded)select 'ca100503-0000-4000-8000-000000000004','ca100502-0000-4000-8000-000000000003','photo','renders','renders/'||org||'/ca100502-0000-4000-8000-000000000003/unuploaded-portrait.jpg',false from card_fixture where actor='ca100501-0000-4000-8000-000000000003';
update orgs set brand_kit=brand_kit||jsonb_build_object('headshot_url','https://cdn.fixture.invalid/renders/'||id||'/ca100502-0000-4000-8000-000000000003/unuploaded-portrait.jpg')where id=(select org from card_fixture where actor='ca100501-0000-4000-8000-000000000003');
set local role service_role;
select pg_temp.card_ok('unuploaded legacy portrait is not public',(public_listing_agent_identity('ca100502-0000-4000-8000-000000000003')->'legacy_portrait')='null');
reset role;
update orgs set brand_kit=brand_kit||'{"headshot_url":"https://unowned.fixture.invalid/unbound.jpg"}'where id=(select org from card_fixture where actor='ca100501-0000-4000-8000-000000000003');
set local role service_role;
select pg_temp.card_ok('unbound or foreign legacy portrait is not public',(public_listing_agent_identity('ca100502-0000-4000-8000-000000000003')->'legacy_portrait')='null');
reset role;
update listings set agent_id='ca100501-0000-4000-8000-000000000001'where id='ca100502-0000-4000-8000-000000000003';
set local role service_role;
select pg_temp.card_ok('foreign assigned profile without membership has no public identity',(public_listing_agent_identity('ca100502-0000-4000-8000-000000000003')->'personal_card')='null' and (public_listing_agent_identity('ca100502-0000-4000-8000-000000000003')->'profile_name')='null');
reset role;
update listings set agent_id='ca100501-0000-4000-8000-000000000003'where id='ca100502-0000-4000-8000-000000000003';
update orgs set deleted_at=now()where id=(select org from card_fixture where actor='ca100501-0000-4000-8000-000000000003');
set local role service_role;
select pg_temp.card_denied('deleted workspace cannot expose personal card','select public_listing_agent_identity(''ca100502-0000-4000-8000-000000000003'')','RP404');
reset role;
select count(*)as card_assertions from card_checks;
select 'PASS: personal card SQL assertions; all fixtures rolled back.';
rollback;
